def match_parens(lst):
    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    for s in lst:
        if not all(c in ['(', ')'] for c in s):
            return 'No'

    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    def generate_combinations(s1, s2):
        if not s1 and not s2:
            return ['']
        if not s1:
            return [s2]
        if not s2:
            return [s1]

        return [s1 + s2, s2 + s1]

    for combination in generate_combinations(lst[0], lst[1]):
        if is_balanced(combination):
            return 'Yes'

    return 'No'

